// Total PV Energy (lifetime)
// 634: Total PV PowerWh Low (0.1kWh)
// 635: Total PV PowerWh High (0.1kWh)

msg.baseAddr = 634;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 634,
    quantity: 2
};
return msg;

// Day PV Energy (total + per MPPT)
// 629: Day PV total (0.1kWh)
// 630: Day PV-1 (0.1kWh)
// 631: Day PV-2 (0.1kWh)
// 632: Day PV-3 (0.1kWh)
// 633: Day PV-4 (0.1kWh)

msg.baseAddr = 629;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 629,
    quantity: 5
};
return msg;

// MPPT Power
// 772: PV1 input power (1W)
// 773: PV2 input power (1W)
// 774: PV3 input power (1W)
// 775: PV4 input power (1W)

msg.baseAddr = 772;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 772,
    quantity: 4
};
return msg;

// MPPT Voltage/Current
// 776: DC voltage 1 (0.1V)
// 777: DC current 1 (0.1A)
// 778: DC voltage 2 (0.1V)
// 779: DC current 2 (0.1A)
// 780: DC voltage 3 (0.1V)
// 781: DC current 3 (0.1A)
// 782: DC voltage 4 (0.1V)
// 783: DC current 4 (0.1A)

msg.baseAddr = 776;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 776,
    quantity: 8
};
return msg;

// Build PvDeviceState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("PvDeviceState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials ----

// Total Energy 634-635
if (baseAddr === 634) {
    const totalLow = data[0] || 0;   // 634
    const totalHigh = data[1] || 0;  // 635

    const totalKWh = Math.round(u32(totalLow, totalHigh) * 0.1 * 10) / 10;

    flow.set("pvds_part_total_energy", {
        totalPvEnergyKWh: totalKWh
    });
}

// Daily Energy 629-633
else if (baseAddr === 629) {
    const dailyTotal = data[0] || 0;   // 629: Day PV total (0.1kWh)
    const daily1 = data[1] || 0;       // 630: Day PV-1 (0.1kWh)
    const daily2 = data[2] || 0;       // 631: Day PV-2 (0.1kWh)
    const daily3 = data[3] || 0;       // 632: Day PV-3 (0.1kWh)
    const daily4 = data[4] || 0;       // 633: Day PV-4 (0.1kWh)

    flow.set("pvds_part_daily_energy", {
        todayPvEnergyKWh: Math.round(dailyTotal * 0.1 * 10) / 10,
        mppt1DailyKWh: Math.round(daily1 * 0.1 * 10) / 10,
        mppt2DailyKWh: Math.round(daily2 * 0.1 * 10) / 10,
        mppt3DailyKWh: Math.round(daily3 * 0.1 * 10) / 10,
        mppt4DailyKWh: Math.round(daily4 * 0.1 * 10) / 10
    });
}

// MPPT Power 772-775
else if (baseAddr === 772) {
    const p1 = data[0] || 0;  // 772: PV1 power (1W)
    const p2 = data[1] || 0;  // 773: PV2 power (1W)
    const p3 = data[2] || 0;  // 774: PV3 power (1W)
    const p4 = data[3] || 0;  // 775: PV4 power (1W)

    const totalPower = p1 + p2 + p3 + p4;

    flow.set("pvds_part_power", {
        totalPvPowerW: totalPower,
        mppt1PowerW: p1,
        mppt2PowerW: p2,
        mppt3PowerW: p3,
        mppt4PowerW: p4
    });
}

// MPPT Voltage/Current 776-783
else if (baseAddr === 776) {
    const v1 = data[0] || 0;  // 776: DC voltage 1 (0.1V)
    const i1 = data[1] || 0;  // 777: DC current 1 (0.1A)
    const v2 = data[2] || 0;  // 778: DC voltage 2 (0.1V)
    const i2 = data[3] || 0;  // 779: DC current 2 (0.1A)
    const v3 = data[4] || 0;  // 780: DC voltage 3 (0.1V)
    const i3 = data[5] || 0;  // 781: DC current 3 (0.1A)
    const v4 = data[6] || 0;  // 782: DC voltage 4 (0.1V)
    const i4 = data[7] || 0;  // 783: DC current 4 (0.1A)

    flow.set("pvds_part_voltage_current", {
        mppt1: { voltageV: Math.round(v1 * 0.1 * 10) / 10, currentA: Math.round(i1 * 0.1 * 10) / 10 },
        mppt2: { voltageV: Math.round(v2 * 0.1 * 10) / 10, currentA: Math.round(i2 * 0.1 * 10) / 10 },
        mppt3: { voltageV: Math.round(v3 * 0.1 * 10) / 10, currentA: Math.round(i3 * 0.1 * 10) / 10 },
        mppt4: { voltageV: Math.round(v4 * 0.1 * 10) / 10, currentA: Math.round(i4 * 0.1 * 10) / 10 }
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const totalEnergyPart = flow.get("pvds_part_total_energy");
const dailyEnergyPart = flow.get("pvds_part_daily_energy");
const powerPart = flow.get("pvds_part_power");
const voltageCurrentPart = flow.get("pvds_part_voltage_current");

if (!totalEnergyPart || !dailyEnergyPart || !powerPart || !voltageCurrentPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100";

// Helper to determine if MPPT is active
function isMpptActive(powerW, voltageV) {
    return powerW > 0 || voltageV > 0;
}

const state = {
    kind: "PvDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    totalPvPowerW: powerPart.totalPvPowerW,
    todayPvEnergyKWh: dailyEnergyPart.todayPvEnergyKWh,
    totalPvEnergyKWh: totalEnergyPart.totalPvEnergyKWh,

    mppt: [
        {
            pvChannelId: 1,
            isActive: isMpptActive(powerPart.mppt1PowerW, voltageCurrentPart.mppt1.voltageV),
            dcVoltageV: voltageCurrentPart.mppt1.voltageV,
            dcCurrentA: voltageCurrentPart.mppt1.currentA,
            inputPowerW: powerPart.mppt1PowerW,
            todayEnergyKWh: dailyEnergyPart.mppt1DailyKWh
        },
        {
            pvChannelId: 2,
            isActive: isMpptActive(powerPart.mppt2PowerW, voltageCurrentPart.mppt2.voltageV),
            dcVoltageV: voltageCurrentPart.mppt2.voltageV,
            dcCurrentA: voltageCurrentPart.mppt2.currentA,
            inputPowerW: powerPart.mppt2PowerW,
            todayEnergyKWh: dailyEnergyPart.mppt2DailyKWh
        },
        {
            pvChannelId: 3,
            isActive: isMpptActive(powerPart.mppt3PowerW, voltageCurrentPart.mppt3.voltageV),
            dcVoltageV: voltageCurrentPart.mppt3.voltageV,
            dcCurrentA: voltageCurrentPart.mppt3.currentA,
            inputPowerW: powerPart.mppt3PowerW,
            todayEnergyKWh: dailyEnergyPart.mppt3DailyKWh
        },
        {
            pvChannelId: 4,
            isActive: isMpptActive(powerPart.mppt4PowerW, voltageCurrentPart.mppt4.voltageV),
            dcVoltageV: voltageCurrentPart.mppt4.voltageV,
            dcCurrentA: voltageCurrentPart.mppt4.currentA,
            inputPowerW: powerPart.mppt4PowerW,
            todayEnergyKWh: dailyEnergyPart.mppt4DailyKWh
        }
    ]
};

// Clear partials
flow.set("pvds_part_total_energy", null);
flow.set("pvds_part_daily_energy", null);
flow.set("pvds_part_power", null);
flow.set("pvds_part_voltage_current", null);

flow.set("pvDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Only handle messages that came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;
